def deduplicar_go_cuotas(apps, schema_editor):
    """En algún momento se creó 'Go cuotas' a mano (desde "Nuevo Arancel",
    antes de que el método existiera en el catálogo estándar) y después la
    migración 0109 creó 'Go Cuotas' con el nombre canónico -- como el
    nombre es case-sensitive, quedaron como dos MetodoPago distintos.
    Fusiona todas las variantes en una sola, reasignando cualquier
    ArancelMetodoTienda/MetodoPagoTienda de las duplicadas (sin pisar una
    combinación que ya exista en la canónica) antes de borrarlas."""
    MetodoPago = apps.get_model('inventario', 'MetodoPago')
    ArancelMetodoTienda = apps.get_model('inventario', 'ArancelMetodoTienda')
    MetodoPagoTienda = apps.get_model('inventario', 'MetodoPagoTienda')

    variantes = list(MetodoPago.objects.filter(nombre__iexact='Go Cuotas'))
    if len(variantes) <= 1:
        return

    canonico = next((m for m in variantes if m.nombre == 'Go Cuotas'), None)
    if not canonico:
        canonico = max(variantes, key=lambda m: ArancelMetodoTienda.objects.filter(metodo_pago=m).count())

    for duplicado in variantes:
        if duplicado.pk == canonico.pk:
            continue
        for arancel in ArancelMetodoTienda.objects.filter(metodo_pago=duplicado):
            existente = ArancelMetodoTienda.objects.filter(
                tienda=arancel.tienda, metodo_pago=canonico, nombre_plan=arancel.nombre_plan
            ).first()
            if existente:
                # La canónica ya tiene esta combinación (ej. precargada en
                # 0.00% por el backfill default) -- si la duplicada tiene un
                # % real configurado y la canónica sigue en el default sin
                # tocar, se copia; nunca se pisa un % ya distinto de 0 en la
                # canónica, para no perder una edición real.
                if existente.arancel_porcentaje == 0 and arancel.arancel_porcentaje != 0:
                    existente.arancel_porcentaje = arancel.arancel_porcentaje
                    existente.save(update_fields=['arancel_porcentaje'])
                arancel.delete()
            else:
                arancel.metodo_pago = canonico
                arancel.save(update_fields=['metodo_pago'])
        for habilitado in MetodoPagoTienda.objects.filter(metodo_pago=duplicado):
            if MetodoPagoTienda.objects.filter(tienda=habilitado.tienda, metodo_pago=canonico).exists():
                habilitado.delete()
            else:
                habilitado.metodo_pago = canonico
                habilitado.save(update_fields=['metodo_pago'])
        duplicado.delete()


def backfill_metodos_habilitados(apps, schema_editor):
    """Para las tiendas que ya existían antes de este cambio, habilita TODOS
    los métodos (menos Mercado Libre/Tienda Nube, de uso interno) -- así no
    se le apaga a nadie, de un día para el otro, un método que ya estaba
    usando en el Punto de Venta. El default más acotado
    (METODOS_HABILITADOS_DEFAULT) solo aplica de acá en más, a tiendas
    nuevas (ver Tienda.save())."""
    Tienda = apps.get_model('inventario', 'Tienda')
    MetodoPago = apps.get_model('inventario', 'MetodoPago')
    MetodoPagoTienda = apps.get_model('inventario', 'MetodoPagoTienda')

    metodos = list(MetodoPago.objects.exclude(nombre__in=['Mercado Libre', 'Tienda Nube']))
    for tienda in Tienda.objects.all():
        for metodo in metodos:
            MetodoPagoTienda.objects.get_or_create(tienda=tienda, metodo_pago=metodo, defaults={'activo': True})


